edges = [("app", "svc"), ("app", "repo"), ("svc", "repo"), ("web", "svc")]


def instability(m):
    ca = sum(1 for a, b in edges if b == m)
    ce = sum(1 for a, b in edges if a == m)
    return ce / (ca + ce)


