nodes = ["a", "b", "c", "d"]
edges = [("a", "b"), ("b", "c"), ("c", "b"), ("c", "d")]
indeg = {n: 0 for n in nodes}
for _, v in edges:
    indeg[v] += 1
ready, removed = [n for n in nodes if indeg[n] == 0], []
while ready:
    n = ready.pop()
    removed.append(n)
    for u, v in edges:
        if u == n:
            indeg[v] -= 1
            if indeg[v] == 0:
                ready.append(v)
