def parallel(avails):
    down = 1.0
    for a in avails:
        down *= 1 - a
    return 1 - down


print(f"{parallel([0.99, 0.99]):.2%} {parallel([0.99, 0.99, 0.99]):.4%}")

from math import comb


def k_of_n(k, n, a):
    return sum(comb(n, j) * a**j * (1 - a)**(n - j) for j in range(k, n + 1))


print(f"{k_of_n(2, 3, 0.9):.3f} {k_of_n(3, 3, 0.9):.3f}")

class Limit:
    def allowed(self, active): return active < 3

class Generous(Limit):
    def allowed(self, active): return active < 5

def borrow_all(policy):
    n = 0
    while policy.allowed(n):
        n += 1
    return n

print(borrow_all(Limit()), borrow_all(Generous()))

