from collections import deque
graph = {"s": ["a", "b"], "a": ["c"], "b": ["c", "bad"], "c": ["bad"], "bad": []}
parent, queue = {"s": None}, deque(["s"])
while queue:
    node = queue.popleft()
    if node == "bad":
        break
    for nxt in graph[node]:
        if nxt not in parent:
            parent[nxt] = node
            queue.append(nxt)
path = [node]
while parent[path[-1]]:
    path.append(parent[path[-1]])
print(" -> ".join(reversed(path)))
